import React from 'react';
import { PlusCircle, Edit3, Trash2, Clock } from 'lucide-react';

const ActivityFeed = ({ activities = [] }) => {
  const getIcon = (type) => {
    switch (type) {
      case 'added':
        return <PlusCircle size={18} style={{ color: 'var(--status-running)' }} />;
      case 'edited':
        return <Edit3 size={18} style={{ color: 'var(--status-idle)' }} />;
      case 'deleted':
        return <Trash2 size={18} style={{ color: 'var(--status-maintenance)' }} />;
      default:
        return <Clock size={18} style={{ color: 'var(--accent-primary)' }} />;
    }
  };

  const formatTime = (isoString) => {
    if (!isoString) return 'Just now';
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' - ' + date.toLocaleDateString();
  };

  if (!activities || activities.length === 0) {
    return (
      <div style={{ padding: '1.5rem', textAlign: 'center', color: '#0F172A', fontWeight: '700' }}>
        No recent asset activities recorded yet.
      </div>
    );
  }

  return (
    <div className="activity-list" style={{ display: 'flex', flexDirection: 'column', gap: '0.85rem' }}>
      {activities.map((item, index) => (
        <div
          key={item.id || index}
          style={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: '0.85rem',
            padding: '0.85rem 1rem',
            borderRadius: 'var(--radius-sm)',
            background: 'var(--bg-primary)',
            border: '1px solid var(--border-subtle)',
          }}
        >
          <div style={{ marginTop: '3px', flexShrink: 0 }}>{getIcon(item.type)}</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: '0.92rem', color: '#0F172A', fontWeight: '800' }}>
              <span
                style={{
                  color: item.type === 'added' ? 'var(--status-running)' : item.type === 'edited' ? 'var(--status-idle)' : 'var(--status-maintenance)',
                  textTransform: 'capitalize',
                  marginRight: '6px',
                  fontWeight: '800',
                }}
              >
                {item.type}
              </span>
              {item.assetName || item.machineId}
              <span style={{ color: 'var(--accent-primary)', fontSize: '0.85rem', fontWeight: '800', marginLeft: '6px', fontFamily: 'JetBrains Mono, monospace' }}>
                ({item.machineId})
              </span>
            </div>
            {item.details && (
              <div style={{ fontSize: '0.82rem', color: '#334155', marginTop: '2px', fontWeight: '700' }}>
                {item.details}
              </div>
            )}
            <div style={{ fontSize: '0.8rem', color: '#334155', marginTop: '4px', display: 'flex', gap: '0.5rem', alignItems: 'center', fontWeight: '700' }}>
              <span>By {item.user || 'System Engineer'}</span>
              <span>•</span>
              <span style={{ color: '#0F172A' }}>{formatTime(item.timestamp)}</span>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default ActivityFeed;
